   "izenburua": "(13) <img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0664.svg\" alt=\"ker f != &quot;Im&quot; f\" style=\"width:6.637em;height:1.001em\" loading=\"lazy\"> (<img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0059.svg\" alt=\"n\" style=\"width:0.905em;height:1.001em\" loading=\"lazy\"> bakoitia denean)",
