     "mota": "oharra",
     "titulua": "Iturriaren oharrak",
     "blokeak": [
      {
       "mota": "testua",
       "html": "Jatorrizkoak margen gorrian &quot;LA SUMA DE DOS NÚMEROS IGUALES NUNCA ES PAR&quot; idazten du; hori <strong>okerra</strong> da (<img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0680.svg\" alt=\"x + x = 2x\" style=\"width:5.736em;height:1.001em\" loading=\"lazy\"> beti bikoitia da), eta egilearen beraren &quot;PAR&quot; ohar beltzak (<img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0681.svg\" alt=\"2x\" style=\"width:1.452em;height:1.001em\" loading=\"lazy\">-ren azpian) kontraesaten du. Frogapenaren muina zuzena da. Aplikazioaren diagraman, <img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0116.svg\" alt=\"x\" style=\"width:0.974em;height:1.001em\" loading=\"lazy\">-etik bi irteera dituen gezian gorriz &quot;X&quot; bat dago: aplikazio batek ezin dio elementu berari bi irudi eman. Erdiko kurbak eta <img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0682.svg\" alt=\"x^2 + y^2 = 1\" style=\"width:6.063em;height:1.001em\" loading=\"lazy\"> zirkunferentziak (&quot;MAL&quot; markatuak) zuzen bertikal bat behin baino gehiagotan ebakitzen dute, beraz ez dira <img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0116.svg\" alt=\"x\" style=\"width:0.974em;height:1.001em\" loading=\"lazy\">-en funtzioen grafikoak. &quot;<img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0683.svg\" alt=\"n : n\" style=\"width:2.565em;height:1.001em\" loading=\"lazy\"> impar&quot; eta &quot;DEMOSTRADO&quot; ondorengo ikur gorria (<img class=\"formula\" src=\"media/formulak/01ma_01espazioak/f0684.svg\" alt=\"!\" style=\"width:0.532em;height:1.001em\" loading=\"lazy\">?) irakurketa zalantzazkoak dira."
      }
     ]
