     "html": "<img class=\"formula formula-d\" src=\"media/formulak/01ma_01espazioak/f0859.svg\" alt=\"= -20 + 4 lambda + 7 lambda^2 - 77 lambda + 182 - lambda^3 + 11 lambda^2 - 26 lambda = -lambda^3 + 18 lambda^2 - 99 lambda + 162.\" style=\"width:39.585em;height:1.265em\" loading=\"lazy\">"
