     "html": "<img class=\"formula formula-d\" src=\"media/formulak/01ma_01espazioak/f0912.svg\" alt=\"f(x, y, z, t) = f(lambda (0, 1, -1, 1) + mu (0, 1, 0, 1) + delta (1, 0, 0, 0) + epsilon (0, 0, 1, 1))\" style=\"width:35.358em;height:1.364em\" loading=\"lazy\">"
