     "html": "<img class=\"formula formula-d\" src=\"media/formulak/01ma_01espazioak/f1117.svg\" alt=\"arrow(S)_1 subset.eq arrow(S)_2, quad arrow(S)_2 subset.eq arrow(S)_1, quad arrow(S)_1 = arrow(S)_2.\" style=\"width:15.539em;height:1.615em\" loading=\"lazy\">"
